"""Writes the Gamepads preferences' icon (an HVIF vector_icon) into
src/preferences/gamepads/GamepadsIcon.rdef:

    3rdparty/ce/tools/make_gamepads_icon.py > \\
        src/preferences/gamepads/GamepadsIcon.rdef
    3rdparty/ce/tools/make_gamepads_icon.py --preview icon.png

The picture: a gamepad seen from above and slightly from the front, tilted
like Haiku's three-quarter view, with its depth showing under the front
edge; a body in the Renga leaf green, a dark D-pad and sticks, and the
face buttons and guide button in the palette's orange and gold. Haiku's icon style: lit from the top left, gradients, dark
outlines.
"""

import math
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hvif

GREEN = ((126, 190, 74, 255), (78, 140, 46, 255))
ORANGE = ((240, 128, 40, 255), (196, 84, 22, 255))
GOLD = ((246, 196, 64, 255), (206, 150, 30, 255))
BODY = ((150, 206, 96, 255), (78, 140, 46, 255))
BODY_SIDE = ((70, 126, 40, 255), (48, 92, 28, 255))
OUTLINE = (34, 70, 20, 255)
DARK = ((70, 74, 82, 255), (30, 32, 36, 255))


def tilt(points):
	# a slight three-quarter view: squash vertically, shear to the right
	return [(x + (y - 32) * 0.18, 30 + (y - 32) * 0.72) for x, y in points]


def ellipse(cx, cy, rx, ry, steps=20):
	return [(cx + rx * math.cos(2 * math.pi * i / steps),
		cy + ry * math.sin(2 * math.pi * i / steps)) for i in range(steps)]


def body_outline():
	# top outline of the pad, flat coordinates, clockwise from the top left
	points = []
	# the top edge with shoulders
	points += [(14, 18), (24, 15), (40, 15), (50, 18)]
	# right grip
	points += hvif.arc_points(50, 30, 12, -70, 80, 8)
	points += [(56, 50), (51, 54), (46, 51), (40, 42)]
	# bottom middle
	points += [(24, 42)]
	# left grip
	points += [(18, 51), (13, 54), (8, 50)]
	points += hvif.arc_points(14, 30, 12, 100, 250, 8)
	return points


def build():
	icon = hvif.Icon()
	top = tilt(body_outline())

	# depth: the same outline moved down, drawn first
	depth = [(x, y + 5) for x, y in top]
	icon.polygon(depth, hvif.gradient((8, 40), (56, 60),
		[(0, BODY_SIDE[0]), (255, BODY_SIDE[1])]), outline=(OUTLINE, 3))
	icon.polygon(top, hvif.gradient((10, 14), (50, 52),
		[(0, BODY[0]), (255, BODY[1])]), outline=(OUTLINE, 3))

	# D-pad
	cross = [(13, 25), (17, 25), (17, 21), (21, 21), (21, 25), (25, 25),
		(25, 29), (21, 29), (21, 33), (17, 33), (17, 29), (13, 29)]
	icon.polygon(tilt(cross), hvif.gradient((14, 20), (24, 32),
		[(0, DARK[0]), (255, DARK[1])]))

	# sticks
	for cx, cy in ((25, 37), (39, 37)):
		icon.polygon(tilt(ellipse(cx, cy, 4.2, 4.2)), hvif.gradient(
			(cx - 3, cy - 3), (cx + 3, cy + 3), [(0, DARK[0]),
			(255, DARK[1])]), outline=(OUTLINE, 2))

	# face buttons: north gold, west green, east orange, south green
	for (cx, cy), colour in (((46, 21), GOLD), ((42, 26), ORANGE),
			((50, 26), ORANGE), ((46, 31), GOLD)):
		icon.polygon(tilt(ellipse(cx, cy, 2.6, 2.6, 12)), hvif.gradient(
			(cx - 2, cy - 2), (cx + 2, cy + 2), [(0, colour[0]),
			(255, colour[1])]))

	# the guide button
	icon.polygon(tilt(ellipse(32, 24, 2.4, 2.4, 12)), hvif.gradient(
		(30, 22), (34, 26), [(0, ORANGE[0]), (255, ORANGE[1])]))
	return icon


def rdef():
	data = build().flat()
	hexdata = data.hex().upper()
	lines = ["/*", " * Copyright 2026, Renga contributors.",
		" * Distributed under the terms of the MIT License.", " *",
		" * The Gamepads preferences' icon. Generated by",
		" * 3rdparty/ce/tools/make_gamepads_icon.py; see there.",
		" */", "", "resource vector_icon {"]
	for i in range(0, len(hexdata), 64):
		lines.append("\t$\"%s\"" % hexdata[i:i + 64])
	lines.append("};")
	return "\n".join(lines) + "\n"


if __name__ == "__main__":
	if len(sys.argv) == 3 and sys.argv[1] == "--preview":
		from PIL import Image
		icon = build()
		sheet = Image.new("RGBA", (16 + 32 + 64 + 128 + 40, 140),
			(216, 216, 216, 255))
		x = 8
		for size in (16, 32, 64, 128):
			sheet.paste(icon.preview(size, (216, 216, 216, 255)), (x, 4))
			x += size + 8
		sheet.save(sys.argv[2])
	else:
		print(rdef(), end="")
